BEGIN
  SELECT auction FOR UPDATE; lock lease row; validate holder/epoch;
  SELECT first QUEUED request ORDER BY intake_seq FOR UPDATE;
  validate state, server admission time and integer-cent amount;
  advance auction.version; INSERT one decision;
  UPSERT accepted offer; UPDATE request state;
  INSERT chained event; INSERT notification outbox;
COMMIT; then acknowledge the delivered command when resolved.
